#include <string>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minimumDeletions(string s) {
        int b_count = 0, deletions = 0;
        for (char c : s) {
            if (c == 'b') {
                b_count++;
            } else {
                deletions = min(deletions + 1, b_count);
            }
        }
        return deletions;
    }
};

class Solution {
    public int minimumDeletions(String s) {
        int bCount = 0, deletions = 0;
        for (char c : s.toCharArray()) {
            if (c == 'b') {
                bCount++;
            } else {
                deletions = Math.min(deletions + 1, bCount);
            }
        }
        return deletions;
    }
}

/**
 * @param {string} s
 * @return {number}
 */
var minimumDeletions = function(s) {
    let bCount = 0, deletions = 0;
    for (let i = 0; i < s.length; ++i) {
        if (s[i] === 'b') {
            bCount++;
        } else {
            deletions = Math.min(deletions + 1, bCount);
        }
    }
    return deletions;
};
